package uk.ac.ravensbourne.casevault.web;
import java.util.UUID; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.stereotype.Controller; import org.springframework.validation.BindingResult; import org.springframework.web.bind.annotation.*; import uk.ac.ravensbourne.casevault.security.UserPrincipal; import uk.ac.ravensbourne.casevault.service.*; import uk.ac.ravensbourne.casevault.web.dto.CreateCaseRequest;
@Controller @RequestMapping("/cases") public class CaseController { private final CaseAccessService access; private final CaseManagementService management; public CaseController(CaseAccessService access,CaseManagementService management){this.access=access;this.management=management;} @GetMapping("/new") @PreAuthorize("hasRole('CLIENT_USER')") String createForm(){return "case-form";} @PostMapping @PreAuthorize("hasRole('CLIENT_USER')") String create(@AuthenticationPrincipal UserPrincipal p,@Valid @ModelAttribute CreateCaseRequest request,BindingResult errors){if(errors.hasErrors())return "case-form";return "redirect:/cases/"+management.create(p,request).getId();} @GetMapping("/{id}") @PreAuthorize("isAuthenticated()") @ResponseBody public String view(@AuthenticationPrincipal UserPrincipal principal,@PathVariable UUID id){var c=access.requireView(principal,id);return c.getTitle();} }
